/** The PostgreSQL database DATABASE_URL names (see .env.example), through Sequelize. */
import { Sequelize } from 'sequelize'
import { defineModels, type Models } from './models.js'

export const DATABASE_URL = process.env.DATABASE_URL ?? 'postgresql://app:app@localhost:5432/app'

/** The database: its Sequelize instance (close it with `db.sequelize.close()`) and the model of every table. */
export interface Db {
  sequelize: Sequelize
  models: Models
}

/** The PostgreSQL database at `url`. */
export function createDatabase(url: string = DATABASE_URL): Db {
  const sequelize = new Sequelize(url, { dialect: 'postgres', logging: false, timezone: '+00:00' })
  return { sequelize, models: defineModels(sequelize) }
}

