/** The tables of the database, as Sequelize models. They reflect the database: never sync them with it. */
import { DataTypes, literal, type Model, type ModelStatic, type Sequelize } from 'sequelize'

/** The model of every table */
export interface Models {
  customers: ModelStatic<Model>
  categories: ModelStatic<Model>
  products: ModelStatic<Model>
  orders: ModelStatic<Model>
  orderLines: ModelStatic<Model>
  tags: ModelStatic<Model>
  productTags: ModelStatic<Model>
  auditLog: ModelStatic<Model>
}

/** Defines the model of every table on `sequelize`. */
export function defineModels(sequelize: Sequelize): Models {
  /** The "customers" table. */
  const customers = sequelize.define(
    'customers',
    {
      id: { type: DataTypes.BIGINT, primaryKey: true, autoIncrement: true, allowNull: false },
      email: { type: DataTypes.STRING(120), allowNull: false },
      passwordHash: { type: DataTypes.TEXT, allowNull: false, field: 'password_hash' },
      createdAt: { type: DataTypes.DATE, allowNull: false, defaultValue: literal('CURRENT_TIMESTAMP'), field: 'created_at' },
    },
    {
      tableName: 'customers',
      timestamps: false,
      indexes: [
        { name: 'uq_customers_email', unique: true, fields: ['email'] },
      ],
    },
  )

  /** The "categories" table. */
  const categories = sequelize.define(
    'categories',
    {
      id: { type: DataTypes.BIGINT, primaryKey: true, autoIncrement: true, allowNull: false },
      name: { type: DataTypes.STRING(60), allowNull: false },
    },
    {
      tableName: 'categories',
      timestamps: false,
      indexes: [
        { unique: true, fields: ['name'] },
      ],
    },
  )

  /** The "products" table. */
  // CHECK (price >= 0): Sequelize does not keep CHECK constraints; the services check them
  const products = sequelize.define(
    'products',
    {
      id: { type: DataTypes.BIGINT, primaryKey: true, autoIncrement: true, allowNull: false },
      categoryId: { type: DataTypes.BIGINT, allowNull: false, field: 'category_id', references: { model: 'categories', key: 'id' }, onDelete: 'NO ACTION', onUpdate: 'NO ACTION' },
      name: { type: DataTypes.STRING(100), allowNull: false },
      price: { type: DataTypes.DECIMAL(10, 2), allowNull: false },
      status: { type: DataTypes.STRING(10), allowNull: false },
      version: { type: DataTypes.INTEGER, allowNull: false, defaultValue: 1 },
      deletedAt: { type: DataTypes.DATE, allowNull: true, field: 'deleted_at' },
    },
    {
      tableName: 'products',
      timestamps: false,
      indexes: [
        { name: 'ix_products_status', fields: ['status'] },
        { fields: ['category_id'] },
      ],
    },
  )

  /** The "orders" table. */
  const orders = sequelize.define(
    'orders',
    {
      id: { type: DataTypes.BIGINT, primaryKey: true, autoIncrement: true, allowNull: false },
      customerId: { type: DataTypes.BIGINT, allowNull: false, field: 'customer_id', references: { model: 'customers', key: 'id' }, onDelete: 'NO ACTION', onUpdate: 'NO ACTION' },
      placedAt: { type: DataTypes.DATE, allowNull: false, defaultValue: literal('CURRENT_TIMESTAMP'), field: 'placed_at' },
    },
    { tableName: 'orders', timestamps: false },
  )

  /** The "order_lines" table. */
  const orderLines = sequelize.define(
    'order_lines',
    {
      orderId: { type: DataTypes.BIGINT, primaryKey: true, allowNull: false, field: 'order_id', references: { model: 'orders', key: 'id' }, onDelete: 'CASCADE', onUpdate: 'NO ACTION' },
      line: { type: DataTypes.INTEGER, primaryKey: true, allowNull: false },
      productId: { type: DataTypes.BIGINT, allowNull: false, field: 'product_id', references: { model: 'products', key: 'id' }, onDelete: 'RESTRICT', onUpdate: 'NO ACTION' },
      quantity: { type: DataTypes.INTEGER, allowNull: false },
    },
    { tableName: 'order_lines', timestamps: false },
  )

  /** The "tags" table. */
  const tags = sequelize.define(
    'tags',
    {
      id: { type: DataTypes.BIGINT, primaryKey: true, autoIncrement: true, allowNull: false },
      label: { type: DataTypes.STRING(30), allowNull: false },
    },
    { tableName: 'tags', timestamps: false },
  )

  /** The "product_tags" table. */
  const productTags = sequelize.define(
    'product_tags',
    {
      productId: { type: DataTypes.BIGINT, primaryKey: true, allowNull: false, field: 'product_id', references: { model: 'products', key: 'id' }, onDelete: 'CASCADE', onUpdate: 'NO ACTION' },
      tagId: { type: DataTypes.BIGINT, primaryKey: true, allowNull: false, field: 'tag_id', references: { model: 'tags', key: 'id' }, onDelete: 'CASCADE', onUpdate: 'NO ACTION' },
    },
    { tableName: 'product_tags', timestamps: false },
  )

  /** The "audit_log" table. */
  const auditLog = sequelize.define(
    'audit_log',
    {
      at: { type: DataTypes.DATE, allowNull: false },
      message: { type: DataTypes.TEXT, allowNull: false },
    },
    { tableName: 'audit_log', timestamps: false },
  )
  // The table has no primary key: Sequelize would add an id; rows are told apart by all their columns, for reading only
  auditLog.removeAttribute('id')
  return { customers, categories, products, orders, orderLines, tags, productTags, auditLog }
}

