/** Repository of the "audit_log" table: reads and writes rows, and decides nothing. */
import type { Model, Transaction } from 'sequelize'
import type { Db } from '../database.js'
import { AuditLog } from '../entities/audit-log.js'
import type { Page } from '../paging.js'

/** Where audit_log rows are kept. Services depend only on this interface. */
export interface AuditLogRepository {
  list(offset?: number, limit?: number): Promise<Page<AuditLog>>
}

/** The key of a row, as a list of its key values. */
function keyOf(row: AuditLog): unknown[] {
  return [row.at, row.message]
}

/** Orders two keys value by value. */
function compareKeys(a: unknown[], b: unknown[]): number {
  for (let index = 0; index < a.length; index++) {
    const x = a[index] as number | string
    const y = b[index] as number | string
    if (x < y) return -1
    if (x > y) return 1
  }
  return 0
}

/** The AuditLog of an instance Sequelize read. */
function toEntity(instance: Model): AuditLog {
  const row = instance.get({ plain: true }) as Record<string, unknown>
  return Object.assign(new AuditLog(), {
    at: row.at as Date,
    message: row.message as string,
  })
}

/** Keeps audit_log rows in the database, through Sequelize. It never commits: queries run in the transaction it was given. */
export class SqlAuditLogRepository implements AuditLogRepository {
  constructor(
    private readonly db: Db,
    private readonly transaction: Transaction | null = null,
  ) {}

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<AuditLog>> {
    const { rows, count } = await this.db.models.auditLog.findAndCountAll({ order: [['at', 'ASC'], ['message', 'ASC']], offset, limit, transaction: this.transaction })
    return { items: rows.map(toEntity), total: count, offset, limit }
  }
}

/** Keeps audit_log rows in memory, for tests and for trying the services without a database. */
export class MemoryAuditLogRepository implements AuditLogRepository {
  private readonly rows = new Map<string, AuditLog>()

  private visible(): AuditLog[] {
    return [...this.rows.values()].filter((row) => true).sort((a, b) => compareKeys(keyOf(a), keyOf(b)))
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<AuditLog>> {
    const rows = this.visible()
    return { items: rows.slice(offset, offset + limit), total: rows.length, offset, limit }
  }
}

