/** Operations on categories: what each one checks before it writes. */
import type { CategoryCreate, CategoryRead, CategoryUpdate } from '../dtos/category.js'
import { Category } from '../entities/category.js'
import { ConflictError, NotFoundError, ValidationFailedError, type FieldError } from '../errors.js'
import type { Page } from '../paging.js'
import type { UnitOfWork } from '../unit-of-work.js'

/** Properties a client may send: the database fills the others */
const FIELDS = new Set(['name'])

/** Operations on categories. Each write runs in its own transaction. */
export class CategoryService {
  constructor(private readonly uow: UnitOfWork) {}

  /** Checks the values against the rules of the "categories" table, and the rows they point to; throws ValidationFailedError with every problem. */
  private async validate(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Category | null): Promise<void> {
    const creating = current === null
    const errors: FieldError[] = []
    for (const name of Object.keys(values)) if (!FIELDS.has(name)) errors.push({ field: name, message: 'is not a field of Category' })
    if (!creating) for (const name of Object.keys(values)) if (['id'].includes(name)) errors.push({ field: name, message: 'cannot be changed' })
    {
      const value = values.name
      if (value == null) {
        if (creating || 'name' in values) errors.push({ field: 'name', message: 'is required' })
      } else {
        if (typeof value === 'string' && value.length > 60) errors.push({ field: 'name', message: 'is longer than 60 characters' })
      }
    }
    if (errors.length > 0) throw new ValidationFailedError('Category', errors)
  }

  /** Values that must be unique are not taken by another row. */
  private async checkUnique(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Category | null): Promise<void> {
    {
      const name = ('name' in values ? values.name : current?.name) as string | null | undefined
      if (name != null) {
        const other = await uow.categories.findByName(name)
        if (other !== null && (current === null || other.id !== current.id))
          throw new ConflictError('Category', 'name is already taken', ['name'])
      }
    }
  }

  /** Every check before a write: the values, the rows they point to, the unique values. */
  private async check(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Category | null): Promise<void> {
    await this.validate(uow, values, current)
    await this.checkUnique(uow, values, current)
  }

  /** The Category with this key; NotFoundError when there is none. */
  private async find(uow: UnitOfWork, id: number): Promise<Category> {
    const entity = await uow.categories.findById(id)
    if (entity === null) throw new NotFoundError('Category', id)
    return entity
  }

  /** The Category as services return it. */
  private static read(entity: Category): CategoryRead {
    return { id: entity.id, name: entity.name }
  }

  /** Stores a new Category after checking it. */
  async createCategory(data: CategoryCreate): Promise<CategoryRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      await this.check(uow, values, null)
      const created = await uow.categories.insert(Object.assign(new Category(), values))
      return CategoryService.read(created)
    })
  }

  /** The Category with this key; NotFoundError when there is none. */
  async getCategory(id: number): Promise<CategoryRead> {
    return CategoryService.read(await this.find(this.uow, id))
  }

  /** A page of categories, by primary key. */
  async listCategories(offset = 0, limit = 50): Promise<Page<CategoryRead>> {
    const page = await this.uow.categories.list(offset, limit)
    return { ...page, items: page.items.map((entity) => CategoryService.read(entity)) }
  }

  /** Changes the given values of a Category. */
  async updateCategory(id: number, data: CategoryUpdate): Promise<CategoryRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await this.check(uow, values, current)
      Object.assign(current, values)
      const updated = await uow.categories.update(current)
      return CategoryService.read(updated)
    })
  }

  /** Deletes a Category. */
  async deleteCategory(id: number): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      if ((await uow.products.listByCategoryId(current.id)).length > 0) throw new ConflictError('Category', 'rows of products still point to it', ['products'])
      await uow.categories.delete(current)
    })
  }

  /** The Category with this name, or null. */
  async findCategoryByName(name: string): Promise<CategoryRead | null> {
    const entity = await this.uow.categories.findByName(name)
    return entity === null ? null : CategoryService.read(entity)
  }
}

