import type { OrderCreate, OrderRead, OrderUpdate } from '../dtos/order.js'
import { Order } from '../entities/order.js'
import { NotFoundError, ValidationFailedError, type FieldError } from '../errors.js'
import type { Page } from '../paging.js'
import type { UnitOfWork } from '../unit-of-work.js'

/** Properties a client may send: the database fills the others */
const FIELDS = new Set(['customerId'])

/** Operations on orders. Each write runs in its own transaction. */
export class OrderService {
  constructor(private readonly uow: UnitOfWork) {}

  /** Checks the values against the rules of the "orders" table, and the rows they point to; throws ValidationFailedError with every problem. */
  private async validate(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Order | null): Promise<void> {
    const creating = current === null
    const errors: FieldError[] = []
    for (const name of Object.keys(values)) if (!FIELDS.has(name)) errors.push({ field: name, message: 'is not a field of Order' })
    if (!creating) for (const name of Object.keys(values)) if (['id', 'placedAt'].includes(name)) errors.push({ field: name, message: 'cannot be changed' })
    {
      const value = values.customerId
      if (value == null) {
        if (creating || 'customerId' in values) errors.push({ field: 'customer_id', message: 'is required' })
      }
    }
    {
      const customerId = 'customerId' in values ? values.customerId : current?.customerId
      if (customerId != null && (await uow.customers.findById(customerId as number)) === null)
        errors.push({ field: 'customer_id', message: 'no Customer has this key' })
    }
    if (errors.length > 0) throw new ValidationFailedError('Order', errors)
  }

  /** Every check before a write: the values, the rows they point to, the unique values. */
  private async check(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Order | null): Promise<void> {
