  private static read(entity: Order): OrderRead {
    return { id: entity.id, customerId: entity.customerId, placedAt: entity.placedAt }
  }

  /** Stores a new Order after checking it. */
  async createOrder(data: OrderCreate): Promise<OrderRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      await this.check(uow, values, null)
      const created = await uow.orders.insert(Object.assign(new Order(), values))
      return OrderService.read(created)
    })
  }

  /** The Order with this key; NotFoundError when there is none. */
  async getOrder(id: number): Promise<OrderRead> {
