    const error: unknown = await service.createTag({ ...pick<TagCreate>(newTag(1), CREATE_FIELDS), label: null } as unknown as TagCreate).catch((caught: unknown) => caught)
    expect(error).toBeInstanceOf(ValidationFailedError)
    expect((error as ValidationFailedError).errors.map((item) => item.field)).toEqual(['label'])
  })

  it('says when a row is missing', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new TagService(uow)
    await expect(service.getTag(999999)).rejects.toBeInstanceOf(NotFoundError)
  })

  it('changes a row', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new TagService(uow)
    const n = 1
    const created = await service.createTag(pick<TagCreate>(newTag(1), CREATE_FIELDS))
    const updated = await service.updateTag(created.id, { label: 'changed' })
    expect(updated.label).toBe('changed')
  })

  it('deletes a row', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new TagService(uow)
    const n = 1
    const created = await service.createTag(pick<TagCreate>(newTag(1), CREATE_FIELDS))
    await service.deleteTag(created.id)
    await expect(service.getTag(created.id)).rejects.toBeInstanceOf(NotFoundError)
  })
})

/** Fields of the create DTO */
const CREATE_FIELDS = ['label']

/** The values a DTO takes, from a row the factories made. */
function pick<T>(row: object, fields: readonly string[]): T {
  return Object.fromEntries(Object.entries(row).filter(([name]) => fields.includes(name))) as T
}

